try:
    print('>>> f = getattr')
    print('>>> x = bytearray()')
    print('>>> y = range(0)')
    print('>>> f(x, y)')
    f = getattr
    x = bytearray()
    y = range(0)
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
